const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000

const clockFormatter = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" })
const shortDateFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const shortDateWithYearFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" })
const fullDateFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit", year: "numeric" })
const weekdayDateFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const numericDateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return calendarDayNumber(toDate) - calendarDayNumber(fromDate)
}

export function formatTimestamp(timestamp, format, now = new Date()) {
  const date = parseDate(timestamp)

  if (Number.isNaN(date.getTime())) return timestamp

  switch (format) {
    case "relative":
      return formatRelativeDate(date, now)
    case "clock":
      return clockFormatter.format(date)
    case "short-date":
      return formatShortDate(date, now)
    case "full-date":
      return fullDateFormatter.format(date)
    case "weekday-date":
      return weekdayDateFormatter.format(date)
    case "numeric-date-time":
      return numericDateTimeFormatter.format(date)
    default:
      return timestamp
  }
}

function parseDate(timestamp) {
  const calendarDate = /^(\d{4})-(\d{2})-(\d{2})$/.exec(timestamp)

  if (calendarDate) {
    const [ , year, month, day ] = calendarDate
    return new Date(Number(year), Number(month) - 1, Number(day))
  } else {
    return new Date(timestamp)
  }
}

function formatRelativeDate(date, now) {
  const dayDifference = signedDifferenceInDays(now, date)

  if (dayDifference === 0) {
    return clockFormatter.format(date)
  } else if (dayDifference === 1) {
    return "tomorrow"
  } else if (dayDifference === -1) {
    return "yesterday"
  } else if (dayDifference > 0) {
    return `in ${dayDifference} days`
  } else if (dayDifference >= -6) {
    return `${Math.abs(dayDifference)} days ago`
  } else {
    return formatShortDate(date, now)
  }
}

function formatShortDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return shortDateFormatter.format(date)
  } else {
    return shortDateWithYearFormatter.format(date)
  }
}

function calendarDayNumber(date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / DAY_IN_MILLISECONDS
}
