export function formatTimestampTokens(text, format, now = new Date()) {
  return text?.replace(/\{\{time:([^}]+)\}\}/g, (_, timestamp) => formatTimestamp(timestamp, format, now)) ?? text
}

function parseDate(timestamp) {
  const calendarDate = /^(\d{4})-(\d{2})-(\d{2})$/.exec(timestamp)

  if (calendarDate) {
    const [ , year, month, day ] = calendarDate
    return new Date(Number(year), Number(month) - 1, Number(day))
  } else {
    return new Date(timestamp)
  }
}

function formatRelativeDate(date, now) {
  const dayDifference = signedDifferenceInDays(now, date)

  if (dayDifference === 0) {
    return clockFormatter.format(date)
  } else if (dayDifference === 1) {
    return "tomorrow"
  } else if (dayDifference === -1) {
    return "yesterday"
  } else if (dayDifference > 0) {
    return `in ${dayDifference} days`
  } else if (dayDifference >= -6) {
    return `${Math.abs(dayDifference)} days ago`
  } else {
    return formatShortDate(date, now)
  }
}

function formatShortDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return shortDateFormatter.format(date)
  } else {
    return shortDateWithYearFormatter.format(date)
  }
}

// Turn a timestamp into an integer calendar day in the browser's timezone.
// Using local date components avoids DST days being 23 or 25 hours long.
function calendarDayNumber(date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / DAY_IN_MILLISECONDS
}

